<?php declare(strict_types=1);
// Shared by the on-screen ledger and the immutable tax working-paper export.
$escape=static fn(mixed $value):string=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$balanceMoney=static fn(int $value):string=>number_format($value/100,2,',','.').' €';
$calculation=$balanceReport['calculation'];
$balanceReportDisplay=new \Kulturhus\Verein\BalanceDisplayText($managerLanguageMessages??[]);$balanceReportText=$balanceReportDisplay->text(...);$balanceReportName=$balanceReportDisplay->account(...);
$balanceScreenRows=($balanceReportScreen??false)===true&&is_array($calculation)?\Kulturhus\Verein\BalanceScreenReport::partition($calculation):null;
$balanceIncomeScreen=$balanceScreenRows!==null;$balancePeriodScreen=$balanceIncomeScreen&&isset($balanceReport['period']);$balanceResultLabel=$balancePeriodScreen?'Ergebnis dieses Zeitraums':'Jahresergebnis';
$balanceIncomeMoney=static fn(int $value):string=>$balanceIncomeScreen?'<span class="balance-period-money">'.$balanceMoney($value).'</span>':$balanceMoney($value);
$balancePeriodLabel=isset($balanceReport['period'])?implode('.',array_reverse(explode('-',$balanceReport['period']['start']))).' – '.implode('.',array_reverse(explode('-',$balanceReport['period']['end']))):(string)$balanceReport['year'];
?>
<section class="card"><h2><?= $escape($balanceReportText('Bilanz und Ergebnis')) ?> <?= $escape($balancePeriodLabel) ?></h2>
<p><strong><?= $escape($balanceReportText(match($balanceReport['state']){'closed'=>'Bilanzjournal festgeschrieben','open'=>'Arbeitsstand – noch nicht abgeschlossen','setup'=>'Anfangsbestände fehlen',default=>'Noch nicht eingerichtet'})) ?></strong></p>
<?php if(isset($balanceReport['correction'])): ?><p><strong><?= $escape($balanceReportText('Korrekturabschluss')) ?></strong> · <?= $escape($balanceReport['correction']['reason']??$balanceReport['correction']['proof']['input']['reason']) ?></p><?php endif ?>
<?php if($balanceReport['issues']): ?><ul><?php foreach($balanceReport['issues'] as $issue): ?><li><?= $escape($balanceReportText($issue)) ?></li><?php endforeach ?></ul><?php endif ?>
<?php if($calculation&&$balanceReport['state']!=='setup'): ?>
<?php if(!isset($balanceReport['period'])&&function_exists('url')): require_once __DIR__.'/../../../src/Finance/Balance/BalancePdf.php'; ?>
<p><a class="btn btn-outline theme-secondary button secondary" href="<?= $escape(url(['balance_pdf'=>(string)$balanceReport['year'],'balance_pdf_hash'=>\Kulturhus\Verein\BalancePdf::digest($balanceReport)])) ?>"><?= $escape($balanceReportText('Bilanz, GuV und Anlagen als PDF')) ?></a></p>
<?php endif ?>
<div class="table-scroll" tabindex="0" role="region" aria-label="<?= $escape($balanceReportText('Bilanz')) ?>"><table class="table<?= $balanceScreenRows!==null?' balance-screen-main':'' ?>"><thead><tr><th><?= $escape($balanceReportText('Bilanzposten')) ?></th><th><?= $escape($balanceReportText('Betrag')) ?></th></tr></thead><tbody>
<tr><th colspan="2"><?= $escape($balanceReportText('Vermögen · Aktiva')) ?></th></tr>
<?php foreach($balanceScreenRows['assets']??$calculation['assets'] as $row): ?><tr><td><?= $escape($balanceReportName($row)) ?></td><td><?= $balanceMoney($row['amount_cents']) ?></td></tr><?php endforeach ?>
<tr><th><?= $escape($balanceReportText('Summe Aktiva')) ?></th><th><?= $balanceMoney($calculation['asset_total_cents']) ?></th></tr>
<tr><th colspan="2"><?= $escape($balanceReportText('Kapital und Schulden · Passiva')) ?></th></tr>
<?php foreach([...($balanceScreenRows['capital']??$calculation['capital']),...($balanceScreenRows['liabilities']??$calculation['liabilities'])] as $row): ?><tr><td><?= $escape($balanceReportName($row)) ?></td><td><?= $balanceMoney($row['amount_cents']) ?></td></tr><?php endforeach ?>
<tr><td><?= $escape($balanceReportText($balanceResultLabel)) ?></td><td><?= $balanceMoney($calculation['annual_result_cents']) ?></td></tr>
<tr><th><?= $escape($balanceReportText('Summe Passiva')) ?></th><th><?= $balanceMoney($calculation['passive_total_cents']) ?></th></tr>
</tbody></table></div>
<?php if($balanceScreenRows!==null): ?><p data-balance-screen-note><?= $escape($balanceReportText($balancePeriodScreen?'Konten mit Anfangsbeständen oder Buchungen stehen in der Bilanz. Unbenutzte Nullkonten können Sie gesondert aufklappen. Der Kontennachweis und die Buchungsunterlagen enthalten weiterhin alle Konten.':'Konten mit Anfangsbeständen oder Buchungen stehen in der Bilanz. Unbenutzte Nullkonten können Sie gesondert aufklappen. Der Kontennachweis und das PDF enthalten weiterhin alle Konten.')) ?></p><?php if($balanceScreenRows['unused']): ?><details data-balance-unused-accounts><summary><?= $escape($balanceReportText('Unbenutzte Nullkonten ansehen')) ?> (<?= count($balanceScreenRows['unused']) ?>)</summary><p><?= $escape($balanceReportText('Diese Konten haben keine Anfangsbestände und keine Buchungen. Ein Endsaldo von null allein reicht dafür nicht aus.')) ?></p><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $escape($balanceReportText('Unbenutzte Nullkonten')) ?>"><table class="table"><thead><tr><th><?= $escape($balanceReportText('Konto')) ?></th><th><?= $escape($balanceReportText('Anfangssaldo')) ?></th><th><?= $escape($balanceReportText('Soll')) ?></th><th><?= $escape($balanceReportText('Haben')) ?></th><th><?= $escape($balanceReportText('Endsaldo')) ?></th></tr></thead><tbody><?php foreach($balanceScreenRows['unused'] as $unusedBalanceRow): ?><tr><td><?= $escape($balanceReportName($unusedBalanceRow)) ?></td><td><?= $balanceMoney($unusedBalanceRow['opening_cents']) ?></td><td><?= $balanceMoney($unusedBalanceRow['debit_cents']) ?></td><td><?= $balanceMoney($unusedBalanceRow['credit_cents']) ?></td><td><?= $balanceMoney($unusedBalanceRow['closing_cents']) ?></td></tr><?php endforeach ?></tbody></table></div></details><?php endif;endif ?><h3><?= $escape($balanceReportText('Gewinn- und Verlustrechnung')) ?></h3><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $escape($balanceReportText('Gewinn- und Verlustrechnung')) ?>"><table class="table<?= $balanceIncomeScreen?($balancePeriodScreen?' balance-period-income':' balance-screen-income'):'' ?>"><thead><tr><th><?= $escape($balanceReportText('Vereinsbereich')) ?></th><th><?= $escape($balanceReportText('Erträge')) ?></th><th><?= $escape($balanceReportText('Aufwendungen')) ?></th><th><?= $escape($balanceReportText('Ergebnis')) ?></th></tr></thead><tbody>
<?php foreach($calculation['spheres'] as $key=>$sphere): ?><tr><td<?= $balanceIncomeScreen?' data-label="'.$escape($balanceReportText('Vereinsbereich')).'"':'' ?>><?= $escape($balanceReportText(\Kulturhus\Verein\TaxCatalog::SPHERES[(string)$key])) ?></td><td<?= $balanceIncomeScreen?' data-label="'.$escape($balanceReportText('Erträge')).'"':'' ?>><?= $balanceIncomeMoney($sphere['income_cents']) ?></td><td<?= $balanceIncomeScreen?' data-label="'.$escape($balanceReportText('Aufwendungen')).'"':'' ?>><?= $balanceIncomeMoney($sphere['expense_cents']) ?></td><td<?= $balanceIncomeScreen?' data-label="'.$escape($balanceReportText('Ergebnis')).'"':'' ?>><?= $balanceIncomeMoney($sphere['result_cents']) ?></td></tr><?php endforeach ?>
</tbody><tfoot><tr><th><?= $escape($balanceReportText('Summe')) ?></th><th<?= $balanceIncomeScreen?' data-label="'.$escape($balanceReportText('Erträge')).'"':'' ?>><?= $balanceIncomeMoney($calculation['income_cents']) ?></th><th<?= $balanceIncomeScreen?' data-label="'.$escape($balanceReportText('Aufwendungen')).'"':'' ?>><?= $balanceIncomeMoney($calculation['expense_cents']) ?></th><th<?= $balanceIncomeScreen?' data-label="'.$escape($balanceReportText('Ergebnis')).'"':'' ?>><?= $balanceIncomeMoney($calculation['annual_result_cents']) ?></th></tr></tfoot></table></div>
<details><summary><?= $escape($balanceReportText('Kontennachweis')) ?></summary><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $escape($balanceReportText('Kontennachweis')) ?>"><table class="table"><thead><tr><th><?= $escape($balanceReportText('Konto')) ?></th><th><?= $escape($balanceReportText('Anfangssaldo')) ?></th><th><?= $escape($balanceReportText('Soll')) ?></th><th><?= $escape($balanceReportText('Haben')) ?></th><th><?= $escape($balanceReportText('Endsaldo')) ?></th></tr></thead><tbody><?php foreach($calculation['accounts'] as $row): ?><tr><td><?= $escape($balanceReportName($row)) ?></td><td><?= $balanceMoney($row['opening_cents']) ?></td><td><?= $balanceMoney($row['debit_cents']) ?></td><td><?= $balanceMoney($row['credit_cents']) ?></td><td><?= $balanceMoney($row['closing_cents']) ?></td></tr><?php endforeach ?></tbody></table></div><p><?= $escape($balanceReportText('Salden: Soll positiv, Haben negativ.')) ?></p></details>
<?php endif ?>
<p><?= $escape($balanceReportText('Grundlage: Bilanzjournal. Eine Steuerabgabe erfolgt gesondert.')) ?></p>
<?php if(isset($balanceReport['asset_schedule'])):$assetSchedule=$balanceReport['asset_schedule']; ?>
<?php if(isset($assetSchedule['period'])){foreach($assetSchedule['items'] as &$displayAsset){$displayAsset+= $displayAsset['schedule'];$displayAsset['receipt_number']=$displayAsset['receipt_number']??'';}unset($displayAsset);$assetSchedule['totals']['book_disposals_cents']=array_sum(array_column($assetSchedule['items'],'book_disposals_cents'));} ?>
<details <?= $assetSchedule['issues']?'open':'' ?>><summary><?= $escape($balanceReportText('Anschaffungen und Abschreibungen prüfen')) ?></summary>
<?php if($assetSchedule['issues']): ?><ul><?php foreach($assetSchedule['issues'] as $issue): ?><li><?= $escape($balanceReportText($issue)) ?></li><?php endforeach ?></ul><?php endif ?>
<?php if($assetSchedule['items']): ?>
<?php $showValuation=isset($assetSchedule['totals']['impairment_cents'])||array_filter($assetSchedule['items'],static fn($i)=>($i['impairment_cents']??0)!==0||($i['writeup_cents']??0)!==0); ?>
<div class="table-scroll" tabindex="0" role="region" aria-label="<?= $escape($balanceReportText('Anlagenverzeichnis')) ?>"><table class="table"><thead><tr><th><?= $escape($balanceReportText('Gegenstand / Beleg')) ?></th><th><?= $escape($balanceReportText('Wert am Anfang')) ?></th><th><?= $escape($balanceReportText('Neu angeschafft')) ?></th><th><?= $escape($balanceReportText(isset($balanceReport['period'])?'Abschreibung im Zeitraum':'Planmäßige Abschreibung')) ?></th><?php if($showValuation): ?><th><?= $escape($balanceReportText('Wertminderung')) ?></th><th><?= $escape($balanceReportText('Wertaufholung')) ?></th><?php endif ?><?php if(isset($assetSchedule['totals']['book_disposals_cents'])): ?><th><?= $escape($balanceReportText('Restwert beim Abgang')) ?></th><?php endif ?><th><?= $escape($balanceReportText('Wert am Ende')) ?></th></tr></thead><tbody>
<?php foreach($assetSchedule['items'] as $asset): ?><tr><td><?= $escape(($asset['name']??$asset['item_id']).' · '.$asset['receipt_number']) ?><?php if(isset($asset['disposal'])): ?><br><?= $escape($balanceReportText(match($asset['disposal']['kind']??''){'sale'=>'Verkauft','partial_scrap'=>'Teilweise ausgemustert',default=>'Ausgemustert'})) ?>: <?= $escape($asset['disposal']['date']) ?><?php endif ?></td><td><?= $balanceMoney($asset['book_opening_cents']) ?></td><td><?= $balanceMoney($asset['additions_cents']) ?></td><td><?= $balanceMoney($asset['depreciation_cents']??0) ?></td><?php if($showValuation): ?><td><?= $balanceMoney($asset['impairment_cents']??0) ?></td><td><?= $balanceMoney($asset['writeup_cents']??0) ?></td><?php endif ?><?php if(isset($assetSchedule['totals']['book_disposals_cents'])): ?><td><?= $balanceMoney($asset['book_disposals_cents']??0) ?></td><?php endif ?><td><?= $balanceMoney($asset['book_closing_cents']) ?></td></tr><?php endforeach ?>
</tbody></table></div>
<?php elseif(!$assetSchedule['issues']): ?><p><?= $escape($balanceReportText('Kein Anlagevermögen im Bilanzjournal.')) ?></p><?php endif ?></details>
<?php endif ?>
</section>
